import{e as t,a1 as o,m as i,p as a}from"./chunks/framework.BGh0NSIy.js";const p=JSON.parse('{"title":"Contributing","description":"How to contribute to the project.","frontmatter":{"title":"Contributing","description":"How to contribute to the project.","next":false,"prev":false},"headers":[],"relativePath":"other/contributing.md","filePath":"other/contributing.md"}'),r={name:"other/contributing.md"};function n(s,e,l,h,u,c){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="contribute-guide" tabindex="-1">Contribute Guide <a class="header-anchor" href="#contribute-guide" aria-label="Permalink to &quot;Contribute Guide&quot;">​</a></h1><div class="info custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Some of these steps are easier if you&#39;re in our <a href="https://github.com/fmhy/FMHY/wiki/FMHY-Discord" target="_blank" rel="noreferrer">Discord</a>. It opens every Friday.</p></div><p>Here you&#39;ll find some general guidelines for those who would like to start contributing. There are multiple ways to do this:</p><ul><li><a href="#submissions">Link Submissions</a></li><li><a href="#reporting-a-site">Reporting an Existing Site</a></li><li><a href="#making-changes">How to Edit and Preview Changes</a></li><li><a href="https://www.reddit.com/r/FREEMEDIAHECKYEAH/wiki/find-new-sites/" target="_blank" rel="noreferrer">Finding New Sites</a></li></ul><h2 id="submissions" tabindex="-1">Submissions <a class="header-anchor" href="#submissions" aria-label="Permalink to &quot;Submissions&quot;">​</a></h2><div class="info custom-block github-alert"><p class="custom-block-title">NOTE</p><p>For bigger changes to the wiki, such as debloating efforts or the restructuring of a page/section, you must first discuss these with us via <a href="https://github.com/fmhy/FMHY/wiki/FMHY-Discord" target="_blank" rel="noreferrer">Discord</a> before opening a <a href="https://github.com/fmhy/edit/pulls" target="_blank" rel="noreferrer">Pull Request</a>.</p></div><p><strong>Don&#39;t submit any of the following:</strong></p><ul><li><strong>💰️ Paid / Trial Sites</strong> - We don&#39;t accept any paid or free trial only entries, with the exception of select paid <a href="/privacy#vpn">VPNs</a> and <a href="/downloading#debrid-leeches">Debrid</a>.</li><li><strong>🕹️ Emulators</strong> - Already listed on <a href="/gaming#emulators">Index Sites</a>.</li><li class="index"><strong>🌐 Web Browsers</strong> - Good open-source browsers are already listed, so we just accept indexes, privacy-focused, and good mobile ones.</li><li><strong>🔻 Leeches</strong> - Unless it&#39;s not already listed on existing <a href="/downloading#debrid-leeches">Leech Lists</a>, don&#39;t submit these.</li><li><strong>🐧 Linux Distros</strong> - Already listed on <a href="/linux-macos#linux-distros">Index Sites</a>.</li><li><strong>🌍 Non-english Software</strong> - We don&#39;t add non-english software sites (APKs, games, torrents, etc.) unless they have a very good reputation.</li><li><strong>🗂️ Coding Libraries</strong> - There&#39;s too many of them and there are better places to find them.</li><li><strong>🎲 Mining / Betting Sites</strong> - Don&#39;t submit anything related to betting, mining, BINs, CCs, etc.</li><li><strong>🎮 Multiplayer Hacks</strong> - Don&#39;t submit any hacks or exploits that give an unfair advantage in multiplayer games.</li><li><strong>🖥️ Custom OSs</strong> - We don&#39;t recommend people use these.</li></ul><h3 id="adding-a-site" tabindex="-1">Adding a Site <a class="header-anchor" href="#adding-a-site" aria-label="Permalink to &quot;Adding a Site&quot;">​</a></h3><p>For submitting new links, follow these steps:</p><ul><li>Make sure it&#39;s not already in the wiki. The easiest way to do this is to check our <a href="https://fmhy.net/single-page.md" target="_blank" rel="noreferrer">Single Page</a> / <a href="https://api.fmhy.net/single-page" target="_blank" rel="noreferrer">2</a> using <code>ctrl+f</code>.</li><li>Don&#39;t spam a bunch of un-tested links at once. Try to only send things you genuinely feel might be worth adding.</li><li>Reach out via the feedback system, <a href="https://github.com/fmhy/edit" target="_blank" rel="noreferrer">GitHub</a>, or join our <a href="https://github.com/fmhy/FMHY/wiki/FMHY-Discord" target="_blank" rel="noreferrer">Discord</a>. Note that we have to check sites ourselves, so using a issue, rather than pull request is easier.</li><li>You can optionally include socials, tools, or any other additional info alongside the entry.</li></ul><h3 id="reporting-a-site" tabindex="-1">Reporting a Site <a class="header-anchor" href="#reporting-a-site" aria-label="Permalink to &quot;Reporting a Site&quot;">​</a></h3><div class="info custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If it&#39;s urgent, you&#39;re allowed to request an invite via our feedback system.</p></div><p>For changes to existing entries, follow these steps:</p><ul><li>Reach out via the feedback system, <a href="https://github.com/fmhy/edit" target="_blank" rel="noreferrer">GitHub</a>, or join our <a href="https://github.com/fmhy/FMHY/wiki/FMHY-Discord" target="_blank" rel="noreferrer">Discord</a>.</li><li>Feel free to leave contact info when using the feedback system, if needed. Only trusted staff can view this.</li><li>If you&#39;d like to report a site removal or star change, you must include details as to why your changes should be accepted.</li></ul><h3 id="link-testing" tabindex="-1">Link Testing <a class="header-anchor" href="#link-testing" aria-label="Permalink to &quot;Link Testing&quot;">​</a></h3><p>All additions have to first go through our testing process on <a href="https://github.com/fmhy/FMHY/wiki/FMHY-Discord" target="_blank" rel="noreferrer">Discord</a>.</p><p>You can help us test new sites to figure out their use-case, safety, and whether they&#39;d be a good fit for the wiki.</p><p>Keep in mind certain sites (such as piracy sites) require more testing/vetting before they can be added.</p><h3 id="formatting-rules" tabindex="-1">Formatting Rules <a class="header-anchor" href="#formatting-rules" aria-label="Permalink to &quot;Formatting Rules&quot;">​</a></h3><p>The wiki will always have some variation either due to exceptions being made, the layout/structure, or the flexible nature of markdown itself.</p><p>For these reasons, there are too many conditions and nuances to satisfy to make an easy-to-follow guide. However, you can generally get an idea by looking at how existing links are structured.</p><p>Note that we do try to order sections from best to worst, and if multiple links are on the same line, only the <strong>bold</strong> ones are considered stars.</p><p>If you&#39;re unsure, ask in the wiki channels on <a href="https://github.com/fmhy/FMHY/wiki/FMHY-Discord" target="_blank" rel="noreferrer">Discord</a> and wait for a staff member to reply.</p><h2 id="making-changes" tabindex="-1">Making Changes <a class="header-anchor" href="#making-changes" aria-label="Permalink to &quot;Making Changes&quot;">​</a></h2><p>Instructions on various ways to edit the wiki and preview changes.</p><h3 id="github-editor" tabindex="-1">GitHub Editor <a class="header-anchor" href="#github-editor" aria-label="Permalink to &quot;GitHub Editor&quot;">​</a></h3><p>You can use the built-in web editor in two ways:</p><ol><li><p>Find the file you want to edit, look for the edit icon (of a pencil) and click on it, then make your changes.</p><p><img src="https://files.catbox.moe/7w3hnm.png" alt="Edit Button"></p></li><li><p>When you&#39;re done, click &quot;Commit Changes...&quot; then &quot;Propose changes&quot;. Optionally add a commit description.</p></li><li><p>You should now see a comparison page showing all your edits. Click &quot;Create pull request&quot;, fill in the box describing your changes, then hit submit.</p></li></ol><p><strong>OR</strong></p><ol><li><p>Fork the repository by clicking the &quot;Fork&quot; button in the top right.</p></li><li><p>Navigate to your fork&#39;s homepage and press the <code>.</code> (period) key on your keyboard. This will open the repository in a VSCode-like environment on <code>github.dev</code>.</p></li><li><p>Make your changes, then commit via the source control tab.</p><p><img src="https://files.catbox.moe/pa571v.png" alt="Source Control"></p></li><li><p>Back on your fork&#39;s homepage, click &quot;Contribute&quot; then &quot;Open pull request&quot;.</p></li><li><p>You should now see a comparison page showing all your edits. Click &quot;Create pull request&quot;, fill in the box describing your changes, then hit submit.</p></li></ol><h3 id="dev-environment" tabindex="-1">Dev Environment <a class="header-anchor" href="#dev-environment" aria-label="Permalink to &quot;Dev Environment&quot;">​</a></h3><p>If you&#39;re going to work on the site itself, or simply want to preview the site and any changes, you can do so by setting up a development environment.</p><h4 id="github-codespaces" tabindex="-1">GitHub Codespaces <a class="header-anchor" href="#github-codespaces" aria-label="Permalink to &quot;GitHub Codespaces&quot;">​</a></h4><p>This creates an environment in the browser <a href="https://docs.github.com/en/billing/concepts/product-billing/github-codespaces#free-and-billed-use-by-personal-accounts" target="_blank" rel="noreferrer">(with 60h/month free quota)</a>. To use Codespaces, follow these steps:</p><ol><li><p>Fork the repository by clicking the &quot;Fork&quot; button in the top right.</p></li><li><p>Navigate to your fork&#39;s homepage and click on the green &quot;Code&quot; button above your repository, open &quot;Codespaces&quot; tab and click &quot;Create codespace&quot;.</p></li><li><p>You may have to wait ~5-10 minutes for the codespace to load.</p><p><img src="https://files.catbox.moe/5bp38f.png" alt="Codespace Status"></p></li><li><p>Once it has loaded, run <code>pnpm i &amp;&amp; pnpm docs:dev</code> to start the preview. Then when it appears, click &quot;Open in Browser&quot; in the bottom right.</p></li><li><p>Make your changes and commit.</p></li><li><p>To shut it down, click the &quot;Code&quot; button again and look for the <code>...</code> dropdown next to your codespace, then click &quot;Stop codespace&quot;.</p></li></ol><h4 id="local-instance" tabindex="-1">Local Instance <a class="header-anchor" href="#local-instance" aria-label="Permalink to &quot;Local Instance&quot;">​</a></h4><p>Making changes on a local repository may require a basic understanding of Git. You can find learning resources <a href="/educational#developer-learning">here</a>.</p><p>More info on manual setup can be found <a href="/other/selfhosting">here</a>.</p>',39)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
